SELECT t.id, t.sale_no, t.sale_name, t.status, d.dict_label AS status_name, t.create_time, u.nickname AS creator_name FROM sale_quotation t LEFT JOIN sys_dict_data d ON d.dict_value = t.status::varchar AND d.dict_type = 'audit_status' LEFT JOIN sys_user u ON u.id = t.creator_id
t.is_deleted = false
AND t.sale_no LIKE CONCAT('%', #{query.saleNo}, '%')
AND t.sale_name LIKE CONCAT('%', #{query.saleName}, '%')
AND t.status = #{query.status}
AND t.create_time >= #{query.startDate}
AND t.create_time <= #{query.endDate}
ORDER BY t.create_time DESC

